using System.Security.Cryptography;
using System.Text;
using BuildingFlow.Application;
using BuildingFlow.Domain;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Configuration;
namespace BuildingFlow.Infrastructure;
public sealed class WebsiteDomainStore(BuildingFlowDbContext db,IWebsiteDomainVerifier verifier,TimeProvider clock,IConfiguration config,SessionContextStore contexts):IWebsiteDomainStore{
 private IQueryable<WebsiteSite> Sites(Guid p,AccessScope a)=>db.Set<WebsiteSite>().Where(s=>s.PropertyId==p&&s.IsEnabled&&db.Properties.Any(x=>x.Id==p&&x.IsEnabled&&(a.ReadAll||db.PropertyMemberships.Any(m=>m.PropertyId==p&&m.UserId==a.UserId&&m.IsEnabled)))&&(!contexts.Enabled||contexts.ManagementProperties("SITE_ADMIN").Any(x=>x.PropertyId==p)));
 private async Task<WebsiteSite?> Lock(Guid p,AccessScope a,CancellationToken t){if(!await Sites(p,a).AnyAsync(t))return null;await db.Database.ExecuteSqlInterpolatedAsync($"SELECT 1 FROM properties WHERE id={p} FOR UPDATE",t);return await Sites(p,a).SingleOrDefaultAsync(t);}
 private void Touch(BaseEntity e)=>db.Entry(e).Property(x=>x.IsEnabled).IsModified=true;
 private static WebsiteDomainDto Dto(WebsiteDomain d,string? token=null,bool replay=false)=>new(d.Id,d.HostName,d.Kind,d.Status,d.IsPrimary,d.VerifiedAt,d.LastCheckedAt,d.TlsCheckedAt,d.ApprovedAt,d.Version,token,replay);
 public async Task<IReadOnlyList<WebsiteDomainDto>?> List(Guid p,AccessScope a,CancellationToken t){var site=await Sites(p,a).SingleOrDefaultAsync(t);if(site is null)return null;return(await db.Set<WebsiteDomain>().Where(d=>d.PropertyId==p&&d.SiteId==site.Id).OrderBy(d=>d.HostName).ToArrayAsync(t)).Select(d=>Dto(d)).ToArray();}
 public async Task<WebsiteDomainDto?> Create(Guid p,WebsiteDomainCreate r,AccessScope a,CancellationToken t){await using var tx=await db.Database.BeginTransactionAsync(t);var site=await Lock(p,a,t);if(site is null)return null;await db.Database.ExecuteSqlInterpolatedAsync($"SELECT pg_advisory_xact_lock(hashtextextended({r.HostName},1))",t);var old=await db.Set<WebsiteDomain>().IgnoreQueryFilters().SingleOrDefaultAsync(d=>d.PropertyId==p&&d.SiteId==site.Id&&d.RequestId==r.RequestId,t);if(old is not null){if(old.IsDeleted||old.HostName!=r.HostName||old.Kind!=r.Kind)throw new HierarchyConflictException(ErrorCatalog.WebsiteRequestConflict.Create());return Dto(old,replay:true);}if(await db.Set<WebsiteDomain>().AnyAsync(d=>d.HostName==r.HostName,t))throw new HierarchyConflictException(ErrorCatalog.WebsiteDomainConflict.Create());if(await db.Set<WebsiteDomain>().CountAsync(d=>d.SiteId==site.Id,t)>=10)WebsiteDomainService.Invalid();if(r.Kind=="PLATFORM_SUBDOMAIN"){var platform=config["Website:PlatformDomain"];if(string.IsNullOrWhiteSpace(platform)||!r.HostName.EndsWith("."+WebsiteDomain.Normalize(platform),StringComparison.Ordinal))WebsiteDomainService.Invalid();}
 var token=Convert.ToHexString(RandomNumberGenerator.GetBytes(32)).ToLowerInvariant();var d=new WebsiteDomain(p,site.Id,r.RequestId,r.HostName,r.Kind,WebsiteImage.Sha(Encoding.UTF8.GetBytes(token)));db.Add(d);Touch(site);await db.SaveChangesAsync(t);await tx.CommitAsync(t);return Dto(d,token);
 }
 // System re-check for the Worker: public resolution needs a successful check within 24 hours. A failed probe changes nothing,
 // so a transient DNS/TLS error never drops a primary domain early; a removed TXT record lets the row expire at the 24-hour gate.
 public async Task<int> Recheck(int limit,CancellationToken t){var due=clock.GetUtcNow().AddHours(-6);var rows=await db.Set<WebsiteDomain>().AsNoTracking().Where(d=>d.IsEnabled&&d.Status=="VERIFIED"&&d.LastCheckedAt<due).OrderBy(d=>d.LastCheckedAt).Take(limit).Select(d=>new{d.Id,d.HostName,d.VerificationTokenHash,d.Version}).ToArrayAsync(t);var renewed=0;
 foreach(var row in rows){var result=await verifier.Check(row.HostName,row.VerificationTokenHash,t);if(!result.Dns||!result.Tls)continue;await using var tx=await db.Database.BeginTransactionAsync(t);var d=await db.Set<WebsiteDomain>().SingleOrDefaultAsync(x=>x.Id==row.Id&&x.Version==row.Version&&x.Status=="VERIFIED",t);if(d is null)continue;d.Check(true,true,clock.GetUtcNow());Touch(d);await db.SaveChangesAsync(t);await tx.CommitAsync(t);db.ChangeTracker.Clear();renewed++;}
 return renewed;}
 public async Task<WebsiteDomainDto?> Act(Guid p,Guid id,string action,long version,AccessScope a,CancellationToken t){
 // Network checks run outside the write transaction; the row version and scope are rechecked before commit.
 var initial=await db.Set<WebsiteDomain>().AsNoTracking().SingleOrDefaultAsync(d=>d.Id==id&&d.PropertyId==p&&Sites(p,a).Any(s=>s.Id==d.SiteId),t);if(initial is null)return null;if(initial.Version!=version)throw new HierarchyConflictException(ErrorCatalog.RecordChanged.Create());(bool Dns,bool Tls) result=default;if(action=="VERIFY")result=await verifier.Check(initial.HostName,initial.VerificationTokenHash,t);
 await using var tx=await db.Database.BeginTransactionAsync(t);var site=await Lock(p,a,t);if(site is null)return null;var d=await db.Set<WebsiteDomain>().SingleOrDefaultAsync(d=>d.Id==id&&d.PropertyId==p&&d.SiteId==site.Id,t);if(d is null)return null;if(d.Version!=version)throw new HierarchyConflictException(ErrorCatalog.RecordChanged.Create());var now=clock.GetUtcNow();string? token=null;switch(action){case "APPROVE":if(!a.ReadAll)throw new UnauthorizedAccessException();d.Approve(now);break;case "VERIFY":d.Check(result.Dns,result.Tls,now);break;case "ROTATE":token=Convert.ToHexString(RandomNumberGenerator.GetBytes(32)).ToLowerInvariant();d.Rotate(WebsiteImage.Sha(Encoding.UTF8.GetBytes(token)));break;case "DELETE":d.Disable();db.Remove(d);break;case "DISABLE":d.Disable();break;case "PRIMARY":if(d.Status!="VERIFIED"||d.LastCheckedAt<now.AddHours(-24))throw new HierarchyConflictException(ErrorCatalog.WebsiteDomainUnverified.Create());var old=await db.Set<WebsiteDomain>().Where(x=>x.SiteId==site.Id&&x.PropertyId==p&&x.IsPrimary&&x.Id!=id).ToArrayAsync(t);foreach(var x in old){x.Primary(false);Touch(x);}await db.SaveChangesAsync(t);d.Primary(true);break;default:WebsiteDomainService.Invalid();break;}if(action!="DELETE")Touch(d);Touch(site);await db.SaveChangesAsync(t);await tx.CommitAsync(t);return Dto(d,token);
 }
}
